"""
Design a class to compute the frequency of every word in a text document
"""

class TextAnalyzer:
    def __init__ (self, text):
        self.text = text
        self.tokens = text.split()  
        self.frequency_dict = {} 

    def count_words(self):
        for token in self.tokens: 
            if token in self.frequency_dict: 
                self.frequency_dict[token] += 1
            else: 
                self.frequency_dict[token] = 1
        return self.frequency_dict

if __name__== "__main__": 
    text = "This is a test text. Write a piece of code to find the frequency of each word in this text"
    text_analyzer = TextAnalyzer(text) 
    word_frequency = text_analyzer.count_words() 
    print(word_frequency)
```

